const cStyleCommentReg = /\/\*[\S\s]*?\*\//;
const hashCommentReg = /^\s*#.*$/gm;
const mlCommentReg = /<\!\-\-[\S\s]*?\-\->/;
const commentReg = {
    ts: cStyleCommentReg,
    js: cStyleCommentReg,
    css: cStyleCommentReg,
    java: cStyleCommentReg,
    yml: hashCommentReg,
    yaml: hashCommentReg,
    sh: hashCommentReg,
