};

function extractComment(str, fileExt) {
    const reg = commentReg[fileExt];

    if (!fileExt || !reg || !str) {
        return;
    }

    reg.lastIndex = 0;

    if (fileExt === 'sh' || fileExt === 'yml' || fileExt === 'yaml') {
        let result = str.match(reg);
        return result && result.join('\n');
    }
    else {
        let result = reg.exec(str);
        return result && result[0];
    }
}

